using Jobmate.Domain.Common;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace Jobmate.Infrastructure.Persistence.Configurations;

/// <summary>
/// Shared conventions applied to every entity. Written once so no configuration can
/// accidentally omit a timestamp, and so the audit columns are uniform in the schema.
/// </summary>
public static class BaseConfiguration
{
    /// <summary>
    /// UUID key. The Domain assigns <c>Guid.NewGuid()</c>, so the value must not be
    /// regenerated by the database: related rows in the same unit of work already
    /// reference it before the insert.
    /// </summary>
    public static EntityTypeBuilder<TEntity> HasJobmateKey<TEntity>(this EntityTypeBuilder<TEntity> builder)
        where TEntity : class, IEntity
    {
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).ValueGeneratedNever();

        return builder;
    }

    /// <summary>Maps <c>CreatedAt</c> / <c>UpdatedAt</c> to <c>timestamptz</c>.</summary>
    public static EntityTypeBuilder<TEntity> HasJobmateAuditColumns<TEntity>(this EntityTypeBuilder<TEntity> builder)
        where TEntity : AuditableEntity
    {
        builder.Property(e => e.CreatedAt).HasColumnName("created_at").HasColumnType("timestamptz");
        builder.Property(e => e.UpdatedAt).HasColumnName("updated_at").HasColumnType("timestamptz");

        return builder;
    }
}
